import{_ as a,o,c,a2 as i}from"./chunks/framework.CHeM0PsO.js";const m=JSON.parse('{"title":"Comandos CLI","description":"","frontmatter":{},"headers":[],"relativePath":"es/cli/overview.md","filePath":"es/cli/overview.md","lastUpdated":1784903584000}'),d={name:"es/cli/overview.md"};function r(t,e,n,s,l,p){return o(),c("div",null,[...e[0]||(e[0]=[i('<h1 id="comandos-cli" tabindex="-1">Comandos CLI <a class="header-anchor" href="#comandos-cli" aria-label="Permalink to &quot;Comandos CLI&quot;">​</a></h1><h2 id="descripcion-general" tabindex="-1">Descripción General <a class="header-anchor" href="#descripcion-general" aria-label="Permalink to &quot;Descripción General&quot;">​</a></h2><p>La CLI de <code>swag2mcp</code> es el punto de entrada único para todas las operaciones — desde inicializar un espacio de trabajo y gestionar especificaciones de API hasta iniciar un servidor MCP para integración con LLM. Proporciona <strong>13 comandos</strong> que cubren el ciclo de vida completo del trabajo con especificaciones OpenAPI/Swagger/Postman.</p><h3 id="que-resuelve-la-cli" tabindex="-1">Qué resuelve la CLI <a class="header-anchor" href="#que-resuelve-la-cli" aria-label="Permalink to &quot;Qué resuelve la CLI&quot;">​</a></h3><ul><li><strong>Ciclo de vida del espacio de trabajo</strong> — crear (<code>init</code>), inspeccionar (<code>info</code>, <code>ls</code>), limpiar (<code>clean</code>), actualizar (<code>update</code>) y eliminar (<code>delete</code>) espacios de trabajo y su contenido</li><li><strong>Gestión de especificaciones y colecciones</strong> — agregar (<code>add</code>), listar (<code>ls</code>) y eliminar (<code>delete</code>) especificaciones de API y sus colecciones</li><li><strong>Modos de ejecución</strong> — iniciar el servidor MCP para acceso a herramientas LLM (<code>mcp</code>) o lanzar el explorador TUI interactivo (<code>run</code>)</li><li><strong>Diagnóstico</strong> — validar configuración (<code>validate</code>), mostrar versión (<code>version</code>), mostrar información de ejecución (<code>info</code>)</li><li><strong>Copia de seguridad y restauración</strong> — ciclo completo del espacio de trabajo mediante ZIP (<code>export</code>, <code>import</code>)</li></ul><h3 id="matices-clave" tabindex="-1">Matices clave <a class="header-anchor" href="#matices-clave" aria-label="Permalink to &quot;Matices clave&quot;">​</a></h3><ul><li><strong>Resolución de ruta</strong> — los comandos que aceptan <code>[path]</code> esperan un <strong>directorio de espacio de trabajo</strong> (no una ruta de archivo). Orden de resolución: <code>[path]</code> explícito → directorio actual (<code>./</code>) → <code>~/.swag2mcp/</code>. La CLI agrega <code>swag2mcp.yaml</code> automáticamente. Siempre pase una ruta explícita cuando ejecute como servicio o en la configuración del IDE para evitar cargar el espacio de trabajo incorrecto.</li><li><strong>Especificación vs Colección</strong> — una <strong>especificación</strong> representa un servicio de API lógico (por ejemplo, &quot;Open-Meteo API&quot;), mientras que una <strong>colección</strong> es un archivo OpenAPI/Swagger/Postman. Una especificación puede tener múltiples colecciones.</li><li><strong><code>--version</code></strong> se admite tanto como bandera (<code>swag2mcp --version</code>) como subcomando (<code>swag2mcp version</code>).</li><li><strong><code>add spec</code> / <code>add collection</code></strong> aceptan entrada YAML a través de <code>--yaml</code> (cadena en línea o <code>-</code> para stdin). Redirigir desde un archivo o heredoc evita problemas de comillas del shell con caracteres especiales.</li><li><strong><code>delete</code></strong> requiere un TTY (terminal interactiva). No hay una bandera <code>--force</code> o <code>--yes</code> — siempre solicita selección y confirmación.</li><li><strong><code>mcp</code></strong> es el comando principal para la integración con LLM. Admite tres transportes: <code>stdio</code> (predeterminado), <code>sse</code> y <code>streamable-http</code>. La bandera <code>--disable-llm-auth</code> (predeterminado: <code>true</code>) elimina la herramienta <code>auth</code> de la lista de herramientas MCP, evitando que el LLM vea o solicite tokens. La autenticación sigue funcionando — los tokens se obtienen a través del mecanismo de configuración estándar, no a través del LLM. Este modo se recomienda para <strong>producción</strong> (el LLM nunca tiene acceso a las credenciales). Para <strong>depuración</strong> o cuando se usan tokens de corta duración, establezca <code>--disable-llm-auth=false</code> para permitir que el LLM solicite tokens frescos a través de la herramienta <code>auth</code>.</li><li><strong><code>validate</code></strong> verifica la sintaxis YAML, la estructura de configuración, la existencia de archivos de especificación, el alcance de URL, el formato de especificación (OpenAPI/Swagger/Postman), la configuración de autenticación y la corrección del cliente HTTP. <strong>No</strong> prueba los endpoints de autenticación ni la disponibilidad de endpoints de API.</li><li><strong><code>export</code> / <code>import</code></strong> proporcionan un ciclo completo del espacio de trabajo — el archivo de configuración, los archivos de especificación y los scripts de autenticación se incluyen en el archivo ZIP.</li><li><strong><code>clean</code></strong> elimina los directorios <code>cache/</code> y <code>responses/</code> pero conserva <code>specs/</code> y <code>auth_scripts/</code>. Las respuestas antiguas (&gt;48h) también se limpian automáticamente al iniciar <code>mcp</code>.</li></ul><h2 id="comandos" tabindex="-1">Comandos <a class="header-anchor" href="#comandos" aria-label="Permalink to &quot;Comandos&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Comando</th><th>Descripción</th></tr></thead><tbody><tr><td><a href="/cli/init"><code>init</code></a></td><td>Inicializar un directorio de espacio de trabajo con configuración predeterminada</td></tr><tr><td><a href="/cli/add"><code>add</code></a></td><td>Agregar una especificación o colección a la configuración</td></tr><tr><td><a href="/cli/delete"><code>delete</code></a></td><td>Eliminar una especificación o colección de forma interactiva</td></tr><tr><td><a href="/cli/ls"><code>ls</code></a></td><td>Listar todas las especificaciones y sus colecciones</td></tr><tr><td><a href="/cli/run"><code>run</code></a></td><td>Iniciar el explorador de API TUI interactivo</td></tr><tr><td><a href="/cli/validate"><code>validate</code></a></td><td>Validar la configuración y los archivos de especificación</td></tr><tr><td><a href="/cli/clean"><code>clean</code></a></td><td>Limpiar especificaciones en caché y respuestas de invocación</td></tr><tr><td><a href="/cli/update"><code>update</code></a></td><td>Revalidar, recargar en caché y reindexar todas las especificaciones</td></tr><tr><td><a href="/cli/mcp"><code>mcp</code></a></td><td>Iniciar el servidor MCP para acceso a herramientas LLM</td></tr><tr><td><a href="/cli/version"><code>version</code></a></td><td>Imprimir la versión de swag2mcp</td></tr><tr><td><a href="/cli/info"><code>info</code></a></td><td>Mostrar información detallada de configuración y ejecución</td></tr><tr><td><a href="/cli/import"><code>import</code></a></td><td>Importar archivos de especificación o restaurar espacio de trabajo desde ZIP</td></tr><tr><td><a href="/cli/export"><code>export</code></a></td><td>Exportar espacio de trabajo como copia de seguridad ZIP portátil</td></tr></tbody></table><h2 id="banderas-globales" tabindex="-1">Banderas Globales <a class="header-anchor" href="#banderas-globales" aria-label="Permalink to &quot;Banderas Globales&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Bandera</th><th>Descripción</th></tr></thead><tbody><tr><td><code>--version</code></td><td>Mostrar versión (igual que el subcomando <code>version</code>)</td></tr><tr><td><code>--help</code></td><td>Mostrar ayuda para cualquier comando</td></tr></tbody></table>',11)])])}const g=a(d,[["render",r]]);export{m as __pageData,g as default};
